import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';import '../products/product_detail_screen.dart';class MarketplaceScreen extends StatelessWidget{const MarketplaceScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('products').where('status',isEqualTo:'active').snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return ListTile(title:Text(x['title']??''),subtitle:Text('Rp '+(x['price']??0).toString()),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>ProductDetailScreen(productId:d.id))));}).toList());}));}